import React, { useState } from 'react';
import Sidebar from './Sidebar';
import Footer from './Footer';

const App: React.FC = () => {
  const [activeLink, setActiveLink] = useState<string>('Profile');

  const handleLinkClick = (link: string) => {
    setActiveLink(link);
  };

  return (
    <div className="flex h-screen bg-gray-50">
      <Sidebar activeLink={activeLink} onLinkClick={handleLinkClick} />
      <main className="flex-1 p-6 overflow-y-auto bg-gray-50">
        <h1 className="text-2xl font-bold text-gray-800 mb-6">Dashboard</h1>
        <p className="text-gray-600">
          This is the main content area. Click on the sidebar links to navigate.
        </p>
      </main>
      <Footer user="Alice Johnson" />
    </div>
  );
};

export default App;
```

